def transform(grid):
    """Shear occupied cells leftward by their row distance from the object's bottom."""
    points = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not points:
        return [row[:] for row in grid]
    bottom = max(r for r, _, _ in points)
    out = [[0] * len(grid[0]) for _ in grid]
    for r, c, v in points:
        nc = c + r - bottom
        if 0 <= nc < len(grid[0]):
            out[r][nc] = v
    return out
